-- Update RLS policy for audit_log to use auditor_app instead of auditor
DROP POLICY IF EXISTS "Solo supervisores y auditores pueden ver audit_log" ON public.audit_log;

CREATE POLICY "Auditores aplicativos pueden ver audit_log"
ON public.audit_log
FOR SELECT
USING (has_role(auth.uid(), 'auditor_app'));

-- Update RLS policy for ai_function_logs to use auditor_ia instead of auditor  
DROP POLICY IF EXISTS "Auditores pueden ver logs de IA" ON public.ai_function_logs;

CREATE POLICY "Auditores IA pueden ver logs de IA"
ON public.ai_function_logs
FOR SELECT
USING (has_role(auth.uid(), 'auditor_ia'));

-- Add new auditor roles to the enum
ALTER TYPE public.rol_usuario ADD VALUE IF NOT EXISTS 'auditor_app';
ALTER TYPE public.rol_usuario ADD VALUE IF NOT EXISTS 'auditor_ia';

-- Añadir preferencia de ayuda al wizard en profiles
ALTER TABLE public.profiles 
ADD COLUMN mostrar_ayuda_wizard boolean NOT NULL DEFAULT true;

-- Crear tabla para códigos CPV oficiales de la UE
CREATE TABLE public.cpv_codigos (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  codigo text UNIQUE NOT NULL,
  descripcion text NOT NULL,
  descripcion_en text,
  nivel integer NOT NULL CHECK (nivel BETWEEN 1 AND 5), -- 1=División, 2=Grupo, 3=Clase, 4=Categoría, 5=Subcategoría
  codigo_padre text,
  activo boolean DEFAULT true,
  created_at timestamptz DEFAULT now()
);

-- Índices para búsqueda eficiente
CREATE INDEX idx_cpv_codigo ON public.cpv_codigos(codigo);
CREATE INDEX idx_cpv_codigo_prefix ON public.cpv_codigos(codigo text_pattern_ops);
CREATE INDEX idx_cpv_descripcion_gin ON public.cpv_codigos USING gin(to_tsvector('spanish', descripcion));
CREATE INDEX idx_cpv_nivel ON public.cpv_codigos(nivel);
CREATE INDEX idx_cpv_activo ON public.cpv_codigos(activo) WHERE activo = true;

-- RLS: Lectura pública (datos de referencia)
ALTER TABLE public.cpv_codigos ENABLE ROW LEVEL SECURITY;

CREATE POLICY "CPV códigos son públicos para lectura"
ON public.cpv_codigos
FOR SELECT
USING (true);

-- Solo admins pueden modificar
CREATE POLICY "Solo admins pueden insertar CPV"
ON public.cpv_codigos
FOR INSERT
WITH CHECK (has_role(auth.uid(), 'admin'::rol_usuario));

CREATE POLICY "Solo admins pueden actualizar CPV"
ON public.cpv_codigos
FOR UPDATE
USING (has_role(auth.uid(), 'admin'::rol_usuario));

CREATE POLICY "Solo admins pueden eliminar CPV"
ON public.cpv_codigos
FOR DELETE
USING (has_role(auth.uid(), 'admin'::rol_usuario));

-- Comentario de documentación
COMMENT ON TABLE public.cpv_codigos IS 'Vocabulario Común de Contratación Pública (CPV) oficial de la UE';
COMMENT ON COLUMN public.cpv_codigos.nivel IS '1=División, 2=Grupo, 3=Clase, 4=Categoría, 5=Subcategoría';

-- Mapear los estados antiguos a los nuevos
UPDATE public.expedientes SET estado = 'borrador' WHERE estado = 'ingesta';
UPDATE public.expedientes SET estado = 'en_redaccion' WHERE estado = 'alternativas';
UPDATE public.expedientes SET estado = 'cerrado' WHERE estado = 'aprobado';
UPDATE public.expedientes SET estado = 'con_observaciones' WHERE estado = 'revision';
UPDATE public.expedientes SET estado = 'con_observaciones' WHERE estado = 'incidencia';

-- Actualizar el valor por defecto
ALTER TABLE public.expedientes 
ALTER COLUMN estado SET DEFAULT 'borrador'::estado_expediente;

-- Paso 1: Añadir los nuevos valores al enum existente
ALTER TYPE estado_expediente ADD VALUE IF NOT EXISTS 'en_redaccion';
ALTER TYPE estado_expediente ADD VALUE IF NOT EXISTS 'con_observaciones';
ALTER TYPE estado_expediente ADD VALUE IF NOT EXISTS 'listo_validacion';
ALTER TYPE estado_expediente ADD VALUE IF NOT EXISTS 'en_intervencion';
ALTER TYPE estado_expediente ADD VALUE IF NOT EXISTS 'cerrado';

-- Crear función para que admins puedan ver todos los roles
DROP POLICY IF EXISTS "Admins pueden ver todos los roles" ON public.user_roles;
CREATE POLICY "Admins pueden ver todos los roles" 
ON public.user_roles 
FOR SELECT 
USING (has_role(auth.uid(), 'admin'));

-- Admins pueden asignar roles
DROP POLICY IF EXISTS "Admins pueden asignar roles" ON public.user_roles;
CREATE POLICY "Admins pueden asignar roles" 
ON public.user_roles 
FOR INSERT 
WITH CHECK (has_role(auth.uid(), 'admin'));

-- Admins pueden eliminar roles
DROP POLICY IF EXISTS "Admins pueden eliminar roles" ON public.user_roles;
CREATE POLICY "Admins pueden eliminar roles" 
ON public.user_roles 
FOR DELETE 
USING (has_role(auth.uid(), 'admin'));

-- Admins pueden actualizar roles
DROP POLICY IF EXISTS "Admins pueden actualizar roles" ON public.user_roles;
CREATE POLICY "Admins pueden actualizar roles" 
ON public.user_roles 
FOR UPDATE 
USING (has_role(auth.uid(), 'admin'));

-- Admins pueden ver todos los perfiles
DROP POLICY IF EXISTS "Admins pueden ver todos los perfiles" ON public.profiles;
CREATE POLICY "Admins pueden ver todos los perfiles" 
ON public.profiles 
FOR SELECT 
USING (has_role(auth.uid(), 'admin'));

-- Admins pueden actualizar cualquier perfil
DROP POLICY IF EXISTS "Admins pueden actualizar cualquier perfil" ON public.profiles;
CREATE POLICY "Admins pueden actualizar cualquier perfil" 
ON public.profiles 
FOR UPDATE 
USING (has_role(auth.uid(), 'admin'));

-- Admins pueden ver todo el audit_log
DROP POLICY IF EXISTS "Admins pueden ver audit_log" ON public.audit_log;
CREATE POLICY "Admins pueden ver audit_log" 
ON public.audit_log 
FOR SELECT 
USING (has_role(auth.uid(), 'admin'));
